166	/** Users for admin management, optionally filtered by name/email search. */
167	export async function listUsers(search?: string): Promise<ProfileRow[]> {
168	  const supabase = await createClient();
169	  let query = supabase.from("profiles").select("*");
170	  if (search && search.trim()) {
171	    // Double-quote the value so PostgREST treats reserved chars (, . ( )) as
172	    // literal text rather than filter grammar — closes a filter-injection hole
173	    // in the .or() string. Escape any embedded quote/backslash. `%` still works
174	    // as the ilike wildcard inside the quotes.
175	    const escaped = search.trim().replace(/["\\]/g, "\\$&");
176	    const term = `"%${escaped}%"`;
177	    query = query.or(`full_name.ilike.${term},email.ilike.${term}`);
178	  }
179	  const { data, error } = await query
180	    .order("created_at", { ascending: false })
181	    .limit(100);
182	  if (error) throw error;
183	  return data ?? [];
184	}
